import{T as e,d as t,f as n,j as r,k as i,l as a,o,p as s}from"./runtime-core.esm-bundler-BYTLryno.js";import{c}from"./index-BQu0uDP8.js";var l={},u={class:`min-h-screen bg-slate-50 pb-20`},d={class:`p-4 bg-white border-b flex items-center justify-between`},f={class:`p-4 space-y-5 max-w-3xl mx-auto`},p={class:`pt-2`};function m(c,l){let m=i(`router-link`);return e(),a(`div`,u,[o(`header`,d,[l[1]||=o(`h1`,{class:`text-xl font-bold`},`Privacy Policy`,-1),o(`button`,{onClick:l[0]||=e=>c.$router.back(),class:`text-slate-600`},`Close`)]),o(`main`,f,[l[3]||=t(`<p class="text-xs text-slate-500">Last updated: 2026-03-21</p><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5 space-y-3"><p class="text-slate-700"> We value your privacy. This Privacy Policy explains what information we collect, how we use it, and the choices you have about your information when using the Assalam Co‑operative member portal and mobile app. </p></section><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5"><h2 class="font-bold text-slate-900 mb-2">Information we collect</h2><ul class="list-disc pl-5 text-slate-700 space-y-1"><li>Account details such as membership number, branch, and profile information you provide.</li><li>Transaction and wallet activity necessary to provide services (payments, VTU, loans, etc.).</li><li>Device and usage data such as IP address, browser type, and access times for security and analytics.</li></ul></section><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5"><h2 class="font-bold text-slate-900 mb-2">How we use information</h2><ul class="list-disc pl-5 text-slate-700 space-y-1"><li>To operate, maintain, and improve member services and features.</li><li>To process payments, VTU purchases, loans, and related requests you initiate.</li><li>To protect against fraud, unauthorized access, and other unlawful activity.</li><li>To communicate important updates, receipts, and support messages.</li></ul></section><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5"><h2 class="font-bold text-slate-900 mb-2">Sharing</h2><p class="text-slate-700"> We do not sell your data. We may share limited information with trusted service providers (e.g., payment and VTU partners) strictly to deliver the services you request, subject to confidentiality and legal requirements. </p></section><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5"><h2 class="font-bold text-slate-900 mb-2">Security</h2><p class="text-slate-700"> We implement reasonable technical and organizational measures to protect your data. No method of transmission or storage is 100% secure; please keep your password confidential and enable available security features. </p></section><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5"><h2 class="font-bold text-slate-900 mb-2">Your choices</h2><ul class="list-disc pl-5 text-slate-700 space-y-1"><li>Update your profile information from the Profile page.</li><li>Contact Support to request assistance or data-related inquiries.</li><li>You may close your session anytime by logging out.</li></ul></section><section class="bg-white rounded-3xl shadow-sm border border-slate-100 p-5"><h2 class="font-bold text-slate-900 mb-2">Contact</h2><p class="text-slate-700"> Questions about this Privacy Policy? Reach us via the Support page or email <a href="mailto:support@example.com" class="text-emerald-700 font-semibold hover:underline">support@example.com</a>. </p></section>`,8),o(`div`,p,[s(m,{to:`/policy`,class:`text-emerald-700 font-semibold hover:underline`},{default:r(()=>[...l[2]||=[n(`View Terms / Member Policy`,-1)]]),_:1})])])])}var h=c(l,[[`render`,m]]);export{h as default};